"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[36914],{34318:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Builds the body (Humanoid at `maxHealth`, takes no damage until the service\\nsets `DamageTakenMult`) and makes it the current one.","params":[{"name":"maxHealth","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":141,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"Current","desc":"The live body, or nil.","params":[],"returns":[{"desc":"","lua_type":"Body?\\n"}],"function_type":"static","source":{"line":200,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"SetSegment","desc":"Starts a new segment (kept with the previous one for shots fired before it started).","params":[{"name":"self","desc":"","lua_type":"Body"},{"name":"segment","desc":"","lua_type":"Segment"}],"returns":[],"function_type":"static","source":{"line":207,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"Pose","desc":"Moves the hitboxes to the pose at move time `t` of the current segment\\n(`t` = server time - segment Start when omitted).","params":[{"name":"self","desc":"","lua_type":"Body"},{"name":"t","desc":"","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":249,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"RaycastAt","desc":"Ray test against the body as it was at `serverTime`\\n(`workspace:GetServerTimeNow()` domain), without moving any part. Returns\\nthe hitbox part, the hit point and the distance, or nil. `direction`\'s\\nlength is the ray length.","params":[{"name":"self","desc":"","lua_type":"Body"},{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"direction","desc":"","lua_type":"Vector3"},{"name":"serverTime","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"BasePart?"},{"desc":"","lua_type":"Vector3?"},{"desc":"","lua_type":"number?"}],"function_type":"static","source":{"line":340,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"Parts","desc":"Hitbox parts (for ray exclude lists).","params":[{"name":"self","desc":"","lua_type":"Body"}],"returns":[{"desc":"","lua_type":"{ BasePart }\\n"}],"function_type":"static","source":{"line":370,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}},{"name":"selfCheck","desc":"Edit-mode check (temp body on a planner Slam from the IdleLeft hold). Errors on failure.","params":[],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"static","source":{"line":391,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}}],"properties":[],"types":[],"name":"LeviathanBody","desc":"The Leviathan\'s server body: a Humanoid model with invisible hitboxes in 4\\nzones (`DamageMult` attribute = `LeviathanConfig.ZoneDamage`): Body = one\\ncapsule per spine segment Tail10 -> Neck3, Head = a box, WingL / WingR = a\\nbox each. Boxes are measured from the template meshes. Posed from the same\\nsegment maths the clients animate with ([LeviathanPath]).\\n\\nThe body lives under the server\'s `workspace.CurrentCamera`: Camera children\\ndo not replicate, so moving ~20 hitboxes every frame costs no network, but\\nserver raycasts and overlap queries still see them. Clients draw their own\\nanimated mesh.\\n\\nGun rays test it at the shooter\'s shot time (`RaycastAt`, from\\nLagCompensation); turret rays and AOE queries hit the parts at the current\\npose (`Pose` every Heartbeat).","realm":["Server"],"source":{"line":21,"path":"src/ServerStorage/SharedModules/LeviathanBody.luau"}}')}}]);